const now = new Date();
const receivedAfterDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const iso = (value) => value.toISOString();

return [{
  json: {
    receivedAfter: iso(receivedAfterDate),
    receivedBefore: iso(now),
    windowLabel: `${iso(receivedAfterDate).slice(0, 16)} to ${iso(now).slice(0, 16)} UTC`,
    gmailSearch: 'Medium',
  },
}];

const items = $input.all();
const links = new Map();
let bodyCount = 0;
let candidateCount = 0;
let parseFailureCount = 0;
let rejectedCount = 0;
const blockedHosts = new Set([
  'mail.google.com',
  'support.google.com',
  'help.medium.com',
  'about.medium.com',
  'twitter.com',
  'x.com',
  'facebook.com',
  'linkedin.com',
]);

function decodeHtml(value) {
  return value
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

function decodeBase64Url(value) {
  try {
    return Buffer.from(value.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - value.length % 4) % 4), 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function collectPayloadText(part, output) {
  if (!part || typeof part !== 'object') return;
  const mimeType = String(part.mimeType || '').toLowerCase();
  const data = part.body?.data;
  if (data && (mimeType === 'text/html' || mimeType === 'text/plain')) output.push(decodeBase64Url(data));
  for (const child of part.parts || []) collectPayloadText(child, output);
}

function cleanText(value) {
  return (value || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

function getEmailTimestamp(message) {
  const rawValue = message.internalDate ?? message.date ?? message.headers?.date;
  if (typeof rawValue === 'number' && Number.isFinite(rawValue)) return rawValue;
  const rawText = String(rawValue || '').replace(/^Date:\s*/i, '').trim();
  const timestamp = Date.parse(rawText);
  return Number.isFinite(timestamp) ? timestamp : 0;
}

function isArticleUrl(parsed, anchorText) {
  const host = parsed.hostname.toLowerCase();
  const parts = parsed.pathname.split('/').filter(Boolean);
  if (blockedHosts.has(host) || parts.length === 0) return false;

  const lastPart = parts.at(-1) || '';
  const hasMediumArticleId = /-[a-f0-9]{8,}$/i.test(lastPart);
  const isMediumHost = host === 'medium.com' || host.endsWith('.medium.com');
  if (isMediumHost) return parts.length >= 2 && hasMediumArticleId;

  const hasArticleLikeSlug = lastPart.length >= 24 && /[a-z]/i.test(lastPart);
  return anchorText.length >= 20 || hasArticleLikeSlug || hasMediumArticleId;
}

function parseHttpUrl(rawHref) {
  const match = rawHref.match(/^(https?):\/\/([^/?#]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i);
  if (!match) return null;
  const hostPort = match[2].split('@').pop();
  const hostname = hostPort.replace(/^\[|\]$/g, '').split(':')[0].toLowerCase();
  return {
    protocol: `${match[1].toLowerCase()}:`,
    hostname,
    pathname: match[3] || '/',
    query: (match[4] || '').slice(1),
  };
}

function normaliseUrl(rawHref) {
  const href = decodeHtml(rawHref).replace(/[),.;]+$/, '');
  const parsed = parseHttpUrl(href);
  if (!parsed || !['http:', 'https:'].includes(parsed.protocol)) return null;
  const keptQuery = parsed.query
    .split('&')
    .filter(Boolean)
    .filter((part) => !/^(utm_|source|ref|sk)/i.test(part.split('=')[0]))
    .join('&');
  return {
    parsed,
    url: `${parsed.protocol}//${href.match(/^(https?):\/\/([^/?#]+)/i)[2]}${parsed.pathname}${keptQuery ? `?${keptQuery}` : ''}`,
  };
}

function addLink(rawHref, rawText, emailDate, emailTimestamp) {
  candidateCount += 1;
  try {
    const normalised = normaliseUrl(rawHref);
    if (!normalised) {
      rejectedCount += 1;
      return;
    }
    const { parsed, url } = normalised;
    const anchorText = cleanText(rawText);
    if (!isArticleUrl(parsed, anchorText)) {
      rejectedCount += 1;
      return;
    }
    const existing = links.get(url);
    if (!existing || emailTimestamp >= existing.emailTimestamp) {
      links.set(url, {
        digestTitle: anchorText || url,
        emailDate,
        emailTimestamp,
      });
    }
  } catch {
    parseFailureCount += 1;
  }
}

for (const item of items) {
  const bodies = [];
  const topLevel = item.json || {};
  const emailTimestamp = getEmailTimestamp(topLevel);
  const emailDate = emailTimestamp ? new Date(emailTimestamp).toISOString() : null;
  for (const value of [topLevel.html, topLevel.textAsHtml, topLevel.text, topLevel.snippet]) {
    if (typeof value === 'string') bodies.push(value);
  }
  collectPayloadText(topLevel.payload, bodies);
  for (const body of bodies) {
    bodyCount += 1;
    const anchorPattern = /<a\b[^>]*href=[\"']([^\"']+)[\"'][^>]*>([\s\S]*?)<\/a>/gi;
    for (const match of body.matchAll(anchorPattern)) addLink(match[1], match[2], emailDate, emailTimestamp);
    for (const match of body.matchAll(/https?:\/\/[^\s<>\"']+/g)) addLink(match[0], '', emailDate, emailTimestamp);
  }
}

const articles = [...links.entries()]
  .sort(([, left], [, right]) => right.emailTimestamp - left.emailTimestamp)
  .slice(0, 5)
  .map(([url, details]) => ({
    url,
    digestTitle: details.digestTitle,
    emailDate: details.emailDate,
    emailTimestamp: details.emailTimestamp,
    contentStatus: 'pending',
  }));

if (articles.length === 0) {
  return [{ json: {
    noArticles: true,
    articleCount: 0,
    debug: {
      inputItems: items.length,
      bodyCount,
      candidateCount,
      parseFailureCount,
      rejectedCount,
      bufferType: typeof Buffer,
      firstItemKeys: Object.keys(items[0]?.json || {}),
      firstItemHtmlType: typeof items[0]?.json?.html,
      firstItemHtmlLength: typeof items[0]?.json?.html === 'string' ? items[0].json.html.length : 0,
    },
  } }];
}
return articles.map((article) => ({ json: { ...article, articleCount: articles.length } }));

const sourceUrl = $json.sourceUrl || $json.url;
const sourceArticle = $('Extract article links').all()
  .map((item) => item.json)
  .find((article) => article.url === sourceUrl);
const content = ($json.content || '').slice(0, 60000);
const system = [
  'You are an editor preparing a Chinese weekly report from Medium articles.',
  'Return only valid JSON. Do not use Markdown fences.',
  'Relevant topics are: llm_agent, vibe_coding, open_source.',
  'Only set relevant=true when the article has substantial value for at least one topic.',
  'Only include GitHub URLs that are explicitly present in the article text; never invent repositories.',
  'Output schema: {relevant:boolean, topics:string[], summary:string, why_relevant:string, github_repositories:[{name:string,url:string}]}',
].join('\n');

return { json: {
  ...$json,
  sourceUrl,
  emailDate: $json.emailDate || sourceArticle?.emailDate || null,
  emailTimestamp: $json.emailTimestamp || sourceArticle?.emailTimestamp || 0,
  model: $('Workflow configuration').first().json.llmModel,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: JSON.stringify({ title: $json.title || $json.digestTitle, sourceUrl, article: content }) },
  ],
} };

const source = $('Prepare article for LLM').item.json;
const raw = $json.choices?.[0]?.message?.content;
let result = {};
try {
  const cleaned = typeof raw === 'string' ? raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '') : '{}';
  result = JSON.parse(cleaned);
} catch (error) {
  result = { relevant: false, topics: [], summary: '', why_relevant: `LLM JSON parse failed: ${error.message}`, github_repositories: [] };
}

return { json: {
  sourceUrl: source.sourceUrl,
  freediumUrl: source.freediumUrl,
  title: source.title || source.digestTitle,
  author: source.author || null,
  emailDate: source.emailDate || null,
  emailTimestamp: source.emailTimestamp || 0,
  contentStatus: 'success',
  relevant: result.relevant === true,
  topics: Array.isArray(result.topics) ? result.topics : [],
  summary: result.summary || '',
  why_relevant: result.why_relevant || '',
  github_repositories: Array.isArray(result.github_repositories) ? result.github_repositories : [],
} };

const sourceUrl = $json.sourceUrl || $json.url;
const sourceArticle = $('Extract article links').all()
  .map((item) => item.json)
  .find((article) => article.url === sourceUrl);

return { json: {
  sourceUrl,
  freediumUrl: $json.freediumUrl || null,
  title: $json.title || sourceArticle?.digestTitle || 'Untitled article',
  author: null,
  emailDate: $json.emailDate || sourceArticle?.emailDate || null,
  emailTimestamp: $json.emailTimestamp || sourceArticle?.emailTimestamp || 0,
  contentStatus: 'failed',
  relevant: false,
  topics: [],
  summary: '',
  why_relevant: `Full text unavailable: ${$json.error || 'unknown error'}`,
  github_repositories: [],
} };

const articles = $input.all().map((item) => item.json)
  .sort((left, right) => {
    const leftTime = Number(left.emailTimestamp) || Date.parse(left.emailDate || '') || 0;
    const rightTime = Number(right.emailTimestamp) || Date.parse(right.emailDate || '') || 0;
    return rightTime - leftTime;
  });
const relevant = articles.filter((article) => article.relevant === true);
const byTopic = new Map();
for (const article of relevant) {
  for (const topic of article.topics || []) {
    if (!byTopic.has(topic)) byTopic.set(topic, []);
    byTopic.get(topic).push(article);
  }
}

const sections = [];
for (const [topic, topicArticles] of byTopic) {
  sections.push(`\n## ${topic}\n${topicArticles.map((article) => {
    const repos = (article.github_repositories || []).map((repo) => `\n  - GitHub: ${repo.name || repo.url} - ${repo.url}`).join('');
    return `### ${article.title}\n${article.summary || 'No summary'}\n\n${article.why_relevant || ''}\n\nSource: ${article.sourceUrl}${repos}`;
  }).join('\n\n')}`);
}

const failed = articles.filter((article) => article.contentStatus === 'failed');
const window = $('Build rolling 7-day window').first().json;
const emailCount = $('Find Medium Daily Digest emails').all().length;
const report = `# Medium Digest report\n\nWindow: ${window.windowLabel}\nGmail messages matched: ${emailCount}\nProcessed ${articles.length} articles; ${relevant.length} matched your topics.${sections.join('') || '\nNo relevant articles found in the 7-day window.'}\n\n_Articles with unavailable full text: ${failed.length}._`;
return [{ json: { report, emailCount, processed: articles.length, relevant: relevant.length, failed: failed.length } }];

const window = $('Build rolling 7-day window').first().json;
const emailCount = $('Find Medium Daily Digest emails').all().length;
return [{ json: {
  report: `# Medium Digest report\n\nWindow: ${window.windowLabel}\nGmail messages matched: ${emailCount}\nNo Medium article links were found in the 7-day email window.`,
  emailCount,
} }];
